 double mass=result.mass;int inventory=f.batches();auto id=f.recordDish({5,2},"Tomato silk",0,batchId);require(id&&f.dishLayouts.count(id),"record dish from real finished batch");require(f.batches()==inventory&&dock->item->id==batchId&&close(analyse(dock->item->food).mass,mass),"recording does not move, duplicate or transform food");require(json(f.dish(id)->sample)==json(dock->item->food),"recorded reference is the actual result");require(!f.recordDish({5,2},"Wrong batch",0,batchId+100),"recording rejects a stale batch selection");
