 Factory old;old.machines.clear();old.blueprints.clear();old.benchAdd("cream",80);old.benchAdd("vanilla",2);json legacy={{"version",2},{"factory",static_cast<FactoryState&>(old)}};{std::ofstream out(f.storageFile);out<<legacy;}require(loaded.load()&&loaded.bench.batch.parts.empty()&&loaded.machines.size()==1,"old off-floor draft recovered once into a real holding dock");auto recovered=loaded.machines.begin();require(recovered->second.kind==MachineKind::Dispatch&&!recovered->second.automatic&&recovered->second.item&&close(analyse(recovered->second.item->food).mass,82),"migration preserves existing food and holds it for inspection");auto legacyRef=loaded.recordDish(recovered->first,"Recovered vanilla");require(legacyRef&&!loaded.productionLine(legacyRef),"old off-floor provenance cannot create a fabricated production line");require(loaded.save(),"save recovered draft");Factory again;again.storageFile=f.storageFile;require(again.load()&&again.machines.size()==1&&again.batches()==1,"draft recovery does not duplicate material on later loads");
 std::filesystem::remove_all(folder);std::cout<<"PASS floor invention: "<<checks<<" checks; actual machine processing, stock consumption, recorded layouts, no food copying, onward experiments and migration\n";return 0;
